export interface PseudoMetadata {
  filename: string;
  type: 'PAW' | 'USPP' | 'NC' | 'UPF';
  functional: string;
  relativistic: 'Full-Rel' | 'Scalar-Rel';
  valenceHint: string;
}

export function describePseudopotential(filename: string): PseudoMetadata {
  const lower = filename.toLowerCase();
  let type: 'PAW' | 'USPP' | 'NC' | 'UPF' = 'UPF';
  if (lower.includes('kjpaw') || lower.includes('paw')) {
    type = 'PAW';
  } else if (lower.includes('rrkjus') || lower.includes('van') || lower.includes('uspp')) {
    type = 'USPP';
  } else if (lower.includes('mt') || lower.includes('rrkj.') || lower.includes('nc') || lower.includes('hgh')) {
    type = 'NC';
  }

  let functional = 'PBE';
  if (lower.includes('pbesol')) functional = 'PBEsol';
  else if (lower.includes('lda') || lower.includes('pz')) functional = 'LDA';
  else if (lower.includes('pbe')) functional = 'PBE';

  const relativistic = lower.includes('rel-') ? 'Full-Rel' : 'Scalar-Rel';

  let valenceHint = 'Standard';
  const match = lower.match(/\.(?:rel-)?(?:pbesol|pbe|lda|pz)-([a-z]+)-/);
  if (match && match[1]) {
    const code = match[1];
    if (code === 'n') valenceHint = 'Standard valence (n)';
    else if (code === 'nl') valenceHint = 'Nonlinear core-corr (nl)';
    else if (code.includes('spdfn')) valenceHint = 'Semi-core s,p,d,f (spdfn)';
    else if (code.includes('spdn')) valenceHint = 'Semi-core s,p,d (spdn)';
    else if (code.includes('spfn')) valenceHint = 'Semi-core s,p,f (spfn)';
    else if (code.includes('spn') || code.includes('nsp')) valenceHint = 'Semi-core s,p (spn)';
    else if (code.includes('dn') || code.includes('nd')) valenceHint = 'Semi-core d (dn)';
    else valenceHint = `Valence: ${code}`;
  }

  return { filename, type, functional, relativistic, valenceHint };
}

export function getPseudopotentialsForElement(symbol: string): string[] {
  if (!symbol) return [];
  const clean = symbol.trim();
  const normalized = clean.charAt(0).toUpperCase() + clean.slice(1).toLowerCase();
  return PSEUDOPOTENTIALS_BY_ELEMENT[normalized] || [];
}

export function getDefaultPseudopotential(symbol: string): string {
  const list = getPseudopotentialsForElement(symbol);
  if (list.length === 0) {
    return `${symbol}.pbe-n-kjpaw_psl.1.0.0.UPF`;
  }
  // Prefer standard scalar-relativistic PBE PAW from PSLibrary if available
  const preferred =
    list.find(f => f.includes('.pbe-n-kjpaw_psl')) ||
    list.find(f => f.includes('.pbe-spn-kjpaw_psl')) ||
    list.find(f => f.includes('.pbe-dn-kjpaw_psl')) ||
    list.find(f => f.includes('kjpaw_psl')) ||
    list.find(f => f.includes('rrkjus_psl')) ||
    list[0];
  return preferred;
}
